import {Renderer} from './renderer.js';
import {AudioEngine} from './audio.js';
import {Evolution,formNames} from './evolution.js';
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const engine=new AudioEngine(),state=new Evolution();let renderer;
let paused=false,trackWasPlaying=false,selectedDeck=0,deckForms=[0,1],crossfade=.45,loopOn=false,recording=false,loopBeat=0,octave=0,gridShown=false;
const loops=Array.from({length:2},()=>Array.from({length:6},()=>Array(16).fill(false))),speeds=[1,1],jogs=[1,1];let lastSteps=[-1,-1],deckPhases=[0,0],noticeTimer;
function notify(message,persist=false){$('#notice').textContent=message;$('#notice').classList.add('show');clearTimeout(noticeTimer);if(!persist)noticeTimer=setTimeout(()=>$('#notice').classList.remove('show'),3800);}
try{renderer=new Renderer($('#stage'));}catch(error){notify(error.message,true);$('#begin').disabled=true;throw error;}
function started(){document.body.classList.add('started');}
function updateAuto(){const button=$('#auto');button.classList.toggle('on',state.auto);button.setAttribute('aria-pressed',String(state.auto));button.textContent=state.auto?'AUTO':'MANUAL';}
function choose(form,withSound=true){started();state.manual(form);deckForms[selectedDeck]=form;updateAuto();all('[data-form]').forEach(el=>el.classList.toggle('on',Number(el.dataset.form)===form));if(withSound)hit([0,1,2,3,4,5,1,2,2,3][form]);}
function hit(voice,deck=selectedDeck,source='LIVE'){if(paused)return;started();engine.octave=octave;engine.note(voice,.75,deck,crossfade,state.fx).catch(e=>notify(e.message));const gain=deck?Math.sin(crossfade*Math.PI/2):Math.cos(crossfade*Math.PI/2);state.note(voice,.8*gain);if(recording&&source==='LIVE'){const step=Math.round(loopBeat*4)%16;loops[deck][voice][step]=true;drawGrid();}}
function drawGrid(){const host=$('#grid');host.replaceChildren();for(let row=0;row<6;row++){const label=document.createElement('span');label.textContent='ASDJKL'[row];host.append(label);for(let col=0;col<16;col++){const button=document.createElement('button');button.classList.toggle('on',loops[selectedDeck][row][col]);button.setAttribute('aria-label',`${'ASDJKL'[row]} step ${col+1}`);button.setAttribute('aria-pressed',String(loops[selectedDeck][row][col]));button.dataset.step=col;button.onclick=()=>{loops[selectedDeck][row][col]=!loops[selectedDeck][row][col];drawGrid();};host.append(button);}}}
function toggleRecord(){recording=!recording;if(recording){loopOn=true;started();}$('#record').classList.toggle('on',recording);$('#record').setAttribute('aria-pressed',String(recording));$('#loop').classList.toggle('on',loopOn);}
function toggleAuto(){state.auto=!state.auto;state.lastPhrase=-1;updateAuto();all('[data-form]').forEach(el=>el.classList.remove('on'));}
function format(time){return `${Math.floor(time/60)}:${String(Math.floor(time%60)).padStart(2,'0')}`;}
async function load(data,title){started();$('#demo').disabled=true;$('#import').disabled=true;notify('Analyzing music locally...',true);try{const analysis=await engine.load(data,title);state.resetTrack(analysis);paused=false;updateAuto();$('#pause').disabled=false;$('#seek').hidden=false;$('#track-name').textContent=title;$('#demo').textContent='DEMO';notify('Music ready. Drag to orbit or choose a manual form.');}catch(e){notify(`Cannot read audio: ${e.message}. Try MP3 / WAV / OGG / FLAC.`);}finally{$('#demo').disabled=false;$('#import').disabled=false;}}
async function demo(){if(engine.loading)return;if(engine.buffer&&engine.title.startsWith('Technological Messup')){await engine.toggle();return;}try{await engine.unlock();notify('Loading demo...',true);const response=await fetch('assets/music/technological-messup.ogg');if(!response.ok)throw Error('Demo recording unavailable');await load(await response.arrayBuffer(),'Technological Messup · CC0');}catch(e){notify(`${e.message}; you can import a local recording.`);}}
async function importFile(file){if(!file)return;if(engine.loading){notify('An analysis is already running. Please wait.');return;}if(file.size>100*1024*1024){notify('Choose an audio file smaller than 100 MB');return;}if(!/^audio\//.test(file.type)&&!(/\.(mp3|wav|ogg|flac|m4a|aac)$/i).test(file.name)){notify('Choose an MP3 / WAV / OGG / FLAC recording');return;}await load(await file.arrayBuffer(),file.name);}
$('#demo').onclick=demo;$('#begin').onclick=demo;$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{await importFile(e.target.files[0]);e.target.value='';};
$('#pause').onclick=()=>engine.toggle().catch(e=>notify(e.message));$('#auto').onclick=toggleAuto;
$('#seek').oninput=e=>{if(engine.buffer){engine.seek(Number(e.target.value)*engine.buffer.duration);state.lastPhrase=-1;}};
$('#intensity').oninput=e=>state.intensity=Number(e.target.value);
$('#crossfade').oninput=e=>{crossfade=Number(e.target.value);if(!state.auto)state.targetWeights=Array.from({length:10},(_,i)=>(i===deckForms[0]?1-crossfade:0)+(i===deckForms[1]?crossfade:0));};
all('[data-form]').forEach(el=>el.onclick=()=>choose(Number(el.dataset.form)));
all('[data-palette]').forEach(el=>el.onclick=()=>{renderer.palette=Number(el.dataset.palette);all('[data-palette]').forEach(b=>b.classList.toggle('on',b===el));});
$('#loop').onclick=()=>{loopOn=!loopOn;$('#loop').classList.toggle('on',loopOn);if(loopOn)engine.unlock().catch(e=>notify(e.message));};$('#record').onclick=toggleRecord;
$('#grid-toggle').onclick=()=>{gridShown=!gridShown;$('#grid').hidden=!gridShown;$('#grid-toggle').classList.toggle('on',gridShown);if(gridShown)drawGrid();};
$('#help').onclick=()=>$('#guide').showModal();$('#close-guide').onclick=()=>$('#guide').close();$('#hide').onclick=()=>document.body.classList.toggle('artwork');
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{notify('Use the browser fullscreen command');}}
$('#fullscreen').onclick=fullscreen;
function save(){try{localStorage.setItem('recur-web-session',JSON.stringify({version:1,loops,deckForms,crossfade,fx:state.fx,palette:renderer.palette,intensity:state.intensity,weights:state.targetWeights}));renderer.draw(state);$('#stage').toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='RECUR-'+new Date().toISOString().slice(0,19).replaceAll(':','-')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});notify('Image exported. Session saved in this browser.');}catch{notify('Cannot save the session. Check browser storage permissions.');}}
function restore(){try{const data=JSON.parse(localStorage.getItem('recur-web-session'));if(!data||data.version!==1||!Array.isArray(data.loops)||data.loops.length!==2||data.loops.some(deck=>!Array.isArray(deck)||deck.length!==6||deck.some(row=>!Array.isArray(row)||row.length!==16||row.some(v=>typeof v!=='boolean')))||!Array.isArray(data.weights)||data.weights.length!==10||data.weights.some(v=>!Number.isFinite(v)||v<0||v>1)||!Number.isFinite(data.crossfade)||data.crossfade<0||data.crossfade>1||!Array.isArray(data.fx)||data.fx.length!==2||data.fx.some(v=>!Number.isFinite(v)||v<0||v>1)||!Number.isInteger(data.palette)||data.palette<0||data.palette>2||!Array.isArray(data.deckForms)||data.deckForms.length!==2||data.deckForms.some(v=>!Number.isInteger(v)||v<0||v>9))throw Error();for(let d=0;d<2;d++)for(let r=0;r<6;r++)loops[d][r]=data.loops[d][r].slice();deckForms=data.deckForms;crossfade=data.crossfade;state.fx=data.fx;renderer.palette=data.palette;state.targetWeights=data.weights;state.auto=false;state.intensity=Number.isFinite(data.intensity)?Math.max(.25,Math.min(1.4,data.intensity)):.9;$('#crossfade').value=crossfade;$('#intensity').value=state.intensity;updateAuto();drawGrid();started();notify('Session restored. Import the audio file again.');}catch{notify('No saved session is available');}}
$('#save').onclick=save;$('#restore').onclick=restore;
let drag=null;
$('#stage').onpointerdown=e=>{drag={kind:'orbit',x:e.clientX,y:e.clientY};e.currentTarget.setPointerCapture(e.pointerId);};
$('#stage').onwheel=e=>{e.preventDefault();renderer.zoom=Math.max(5.3,Math.min(11,renderer.zoom+e.deltaY*.003));};
$('#fx').onpointerdown=e=>{drag={kind:'fx'};e.currentTarget.setPointerCapture(e.pointerId);move(e);};
all('.deck').forEach(el=>{el.onpointerdown=e=>{selectedDeck=Number(el.dataset.deck);all('.deck').forEach(b=>b.style.borderColor=b===el?'#d3b77d':'#a9936260');if(gridShown)drawGrid();drag={kind:'jog',deck:selectedDeck,x:e.clientX,y:e.clientY};el.setPointerCapture(e.pointerId);};el.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){speeds[Number(el.dataset.deck)]=e.key==='ArrowRight'?1.5:.5;setTimeout(()=>speeds[Number(el.dataset.deck)]=1,300);}};});
function move(e){if(!drag)return;if(drag.kind==='orbit'){renderer.orbit[0]+=(e.clientX-drag.x)*.003;renderer.orbit[1]=Math.max(-1.3,Math.min(1.3,renderer.orbit[1]+(e.clientY-drag.y)*.003));drag.x=e.clientX;drag.y=e.clientY;}if(drag.kind==='fx'){const r=$('#fx').getBoundingClientRect();state.fx=[Math.max(0,Math.min(1,(e.clientX-r.x)/r.width)),1-Math.max(0,Math.min(1,(e.clientY-r.y)/r.height))];$('#fx i').style.left=state.fx[0]*100+'%';$('#fx i').style.top=(1-state.fx[1])*100+'%';}if(drag.kind==='jog'){speeds[drag.deck]=Math.max(.25,Math.min(1.8,1+(e.clientX-drag.x)*.025));drag.x=e.clientX;}}
window.addEventListener('pointermove',move);window.addEventListener('pointerup',()=>{if(drag?.kind==='jog')speeds[drag.deck]=1;drag=null;});window.addEventListener('pointercancel',()=>{speeds[0]=speeds[1]=1;drag=null;});
function pauseAll(){paused=!paused;if(paused){trackWasPlaying=engine.playing;engine.pause();state.holding=false;}else if(trackWasPlaying)engine.start();notify(paused?'Paused':'Playback resumed');}
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName)||$('#guide').open||e.metaKey||e.ctrlKey||e.altKey)return;if(e.repeat)return;const key=e.key.toLowerCase(),formKeys='asd jkl'.replace(' ','');if(formKeys.includes(key)){choose(formKeys.indexOf(key));return;}if('4567'.includes(key)){choose(6+'4567'.indexOf(key));return;}if(e.code==='Space'){e.preventDefault();started();state.holding=true;}else if(key==='t')demo();else if(key==='u')$('#file').click();else if(key==='v')engine.toggle();else if(key==='y')toggleAuto();else if(key==='h')document.body.classList.toggle('artwork');else if(key==='f')fullscreen();else if(key==='p')pauseAll();else if(key==='m')notify(engine.mute()?'Muted':'Sound enabled');else if(key==='r')toggleRecord();else if(key==='i')$('#grid-toggle').click();else if(key==='e')save();else if(key==='o')restore();else if(key==='z'||key==='x'){octave=Math.max(-1,Math.min(1,octave+(key==='x'?1:-1)));notify(`Melody octave ${octave>0?'+':''}${octave}`);}else if(key==='tab'){e.preventDefault();selectedDeck=1-selectedDeck;if(gridShown)drawGrid();}else if(key==='?')$('#guide').showModal();else if(key==='escape')document.body.classList.remove('artwork');else if(key==='backspace'){e.preventDefault();state.manual(0);state.targets=[.4,.25,.4,.1,.25,.5,.5,.2];state.charge=0;state.holding=false;renderer.orbit=[0,.23];renderer.zoom=7.3;updateAuto();}});
window.addEventListener('keyup',e=>{if(e.code==='Space')state.release();});window.addEventListener('blur',()=>{state.holding=false;speeds[0]=speeds[1]=1;drag=null;});
window.addEventListener('dragover',e=>{e.preventDefault();document.body.classList.add('dragging');});window.addEventListener('dragleave',e=>{if(!e.relatedTarget)document.body.classList.remove('dragging');});window.addEventListener('drop',e=>{e.preventDefault();document.body.classList.remove('dragging');importFile(e.dataTransfer.files[0]);});
// No telemetry: these read-only diagnostics support local reproducible QA.
window.recur={engine,state,renderer,loops,get status(){return {playing:engine.playing,time:engine.position,events:engine.eventIndex,auto:state.auto,growth:state.growth.slice(),architecture:state.architecture.slice(),weights:state.weights.slice(),frames:frameCount};}};
let last=performance.now(),uiTime=0,frameCount=0;
function frame(now){const dt=Math.min(.1,(now-last)/1000);last=now;frameCount++;for(let d=0;d<2;d++){jogs[d]+=(speeds[d]-jogs[d])*(1-Math.exp(-dt*12));if(!paused)deckPhases[d]+=dt*jogs[d]*1.8;all('.deck i')[d].style.transform=`rotate(${deckPhases[d]}rad)`;}if(engine.playing)engine.setRate((jogs[0]*(1-crossfade)+jogs[1]*crossfade)*(state.holding?.35:1));
 if(!paused&&loopOn){loopBeat+=dt*108/60;for(let d=0;d<2;d++){const step=Math.floor(loopBeat*4*jogs[d])%16;if(step!==lastSteps[d])for(let row=0;row<6;row++)if(loops[d][row][step])hit(row,d,'LOOP');lastSteps[d]=step;}}
 state.update(dt,engine,paused,jogs[0]*(1-crossfade)+jogs[1]*crossfade);renderer.draw(state);uiTime+=dt;if(uiTime>.12){uiTime=0;$('#pause').textContent=engine.playing?'Ⅱ':'▶';$('#demo').classList.toggle('on',engine.playing&&engine.title.startsWith('Technological'));if(engine.buffer){$('#track-time').textContent=`${format(engine.position)} / ${format(engine.buffer.duration)}`;$('#seek').value=engine.position/engine.buffer.duration;}if(gridShown)all('#grid [data-step]').forEach(el=>el.classList.toggle('playing',loopOn&&Number(el.dataset.step)===lastSteps[selectedDeck]));}
 $('#stage').dataset.diagnostics=JSON.stringify({frames:frameCount,playing:engine.playing,time:engine.position,context:engine.context?.state,events:engine.eventIndex,auto:state.auto,growth:state.growth,architecture:state.architecture,weights:state.weights,rate:engine.rate});
 requestAnimationFrame(frame);
}requestAnimationFrame(frame);
